class Potion {
  #strength;

  constructor(type, strength) {
    this.type = type;
    this.#strength = strength;
  }

  brew(amount) {
    if (amount > 0) {
      this.#strength += amount;
    }
  }

  dilute(amount) {
    if (amount > 0) {
      this.#strength = Math.max(0, this.#strength - amount);
    }
  }

  getStrength() {
    return this.#strength;
  }

  getType() {
    return this.type;
  }
}

// Example usage:
const healingPotion = new Potion("Healing", 50);
console.log(`Initial Strength: ${healingPotion.getStrength()}`); // Expected: 50
healingPotion.brew(20);
console.log(`After Brewing: ${healingPotion.getStrength()}`); // Expected: 70
healingPotion.dilute(30);
console.log(`After Diluting: ${healingPotion.getStrength()}`); // Expected: 40

// Attempt direct modification (should not work on #strength)
healingPotion.strength = 1000;
console.log(`After failed direct modification: ${healingPotion.getStrength()}`); // Expected: 40

const manaPotion = new Potion("Mana", 75);
console.log(`Mana Potion Strength: ${manaPotion.getStrength()}`); // Expected: 75
manaPotion.dilute(80);
console.log(`Mana Potion after over-dilution: ${manaPotion.getStrength()}`); // Expected: 0

